/* Short action lists keep each council role connected to visible map changes. */
const developedRole=renderRole,settledCell=renderCell,developedDraw=draw,developedRender=render;
render=function(){developedRender();const m=ctry().migration,population=$('stats').lastElementChild?.querySelector('span');if(m&&population)population.textContent='Migration: '+(m.net>=0?'+':'')+m.net+' residents net last turn';};
draw=function(){developedDraw();const value=$('layer').value;$('mapKey').hidden=!['happiness','population'].includes(value);$('mapKey').textContent=value==='happiness'?'🔴 Lower happiness → 🟢 Higher happiness. Inspect a cell for its score.':'Light blue: more housing room. Dark blue: fuller housing. Inspect a cell for residents / capacity.';};
$('layer').onchange=draw;
renderCell=function(){settledCell();const cell=state.cells[cellId];if(!cell.land||cell.country<0)return;const box=document.createElement('section');box.className='community-card';const type=Civic.settlement(cell);box.innerHTML=`<h3>${type?'🏘 '+esc(cell.settlement):'👥 Local community'}</h3><p>😊 Happiness <b>${Math.round(Civic.happiness(state,cell))}/100</b> · 🏠 Housing ${cell.population}/${Civic.capacity(cell)}</p><p>Last results: ${cell.migration.incoming} arrived · ${cell.migration.outgoing} left. People move gradually toward nearby happier cells with room. Movement preserves population.</p>${cell.improvements.length?`<p>Developments: ${cell.improvements.map(k=>Research.applied[k].icon+' '+Research.applied[k].name).join(' · ')}</p>`:''}${type&&cell.country===active?`<label class="field">Settlement name<input id="settlementName" maxlength="60" value="${esc(cell.settlement)}"></label><button id="renameSettlement">Rename ${type.toLowerCase()}</button>`:''}`;$('cell').append(box);if($('renameSettlement')){$('renameSettlement').disabled=state.phase!=='implement';$('settlementName').disabled=state.phase!=='implement';$('renameSettlement').onclick=()=>action(()=>Civic.rename(state,active,'settlement',cellId,$('settlementName').value),'Settlement renamed.');}};
renderRole=function(){developedRole();const c=ctry();const checklist=document.createElement('div');checklist.className='role-checklist';checklist.innerHTML=({economy:'<b>💰 Your turn:</b> balance policy and budgets → plan buildings → arrange needed supplies.',research:'<b>📚 Your turn:</b> choose education → supply discoveries → start a local development project.',military:'<b>🛡 Your turn:</b> check supplies → recruit and move → negotiate and protect communities.'})[role];$('rolePanel').prepend(checklist);
if(role==='economy'){const supplies=document.createElement('p');supplies.className='role-intro';supplies.textContent='Research requests '+Object.entries(Research.kit(c,c.funding)).map(([k,n])=>n+' '+k).join(' + ')+' per turn for discoveries, alongside its money budget. Local development has separate upfront costs.';checklist.after(supplies);const budget=document.createElement('label');budget.className='field';budget.innerHTML=`Local R&D project allowance<input id="developmentAllowance" type="number" min="0" max="200" value="${c.developmentBudget}"><small>Permission to spend shared money on local improvements. Projects also need wood, metal, cloth or food. This allowance draws down when R&D starts a project; it is not extra money.</small>`;supplies.after(budget);$('developmentAllowance').disabled=state.phase!=='implement';$('developmentAllowance').onchange=e=>action(()=>c.developmentBudget=Math.max(0,Math.min(200,Number(e.target.value)||0)));}if(role==='research'){const section=document.createElement('section');section.className='development-panel';const kit=Research.kit(c,c.funding),d=c.development,project=d&&Research.applied[d.type];section.innerHTML=`<h3>🧪 Supplies for national discoveries</h3><p>With the current budget: <b>${Object.entries(kit).map(([k,n])=>Economy.icons[k]+' '+n+' '+k).join(' + ')}</b> each turn. Supplies are charged with research money after production and upkeep. If supplies are missing, discovery research pauses without spending its money. Completed fields use no kit.</p><h3>🛠 Your local development project</h3><p>Choose where your work changes the map. One project at a time per country. Economy has authorized <b>${c.developmentBudget.toFixed(1)} money</b> for local projects. Pay the full resource cost when you start; completion happens in Results. National discoveries continue alongside it.</p>${d?`<article class="mini-card"><strong>${project.icon} ${project.name}</strong><p>${esc(state.cells[d.cell].settlement||'Cell '+d.cell)} · ${d.remaining} turns remaining</p><progress value="${project.turns-d.remaining}" max="${project.turns}"></progress><p>${project.description}</p><button id="visitProject">Show project cell</button><button id="cancelDevelopment">Cancel & return unused share</button><small>Refund = cost × remaining turns ÷ total turns. A captured project's committed resources are lost.</small></article>`:''}<details ${d?'':'open'}><summary>Choose a development project · 6 options</summary>${field('Development location','developmentCell',[['','Choose one of your cells'],...state.cells.filter(x=>x.country===active&&x.land).map(x=>[x.id,(x.settlement||'Cell '+x.id)+' · '+(x.buildings.map(k=>Game.buildings[k].name).join(', ')||'undeveloped')])],state.cells[cellId].country===active?cellId:'','Select a cell here or click it on the map. Economy builds the basic facility; Research improves it.')}<div class="development-grid">${Object.entries(Research.applied).map(([key,p])=>{const reason=Research.reason(state,active,cellId,key);return `<article class="development-card"><img src="research-images/${p.image}.svg" alt=""><h3>${p.icon} ${p.name}</h3><p>${p.description}</p><small>${Object.entries(p.cost).map(([k,n])=>Economy.icons[k]+' '+n+' '+k).join(' · ')} · ${p.turns} turns</small><button data-develop="${key}" ${reason||state.phase!=='implement'?'disabled':''}>${state.cells[cellId].improvements.includes(key)?'Completed here':'Start project'}</button>${reason?`<small>${esc(reason)}</small>`:''}</article>`;}).join('')}</div></details>`;checklist.after(section);$('developmentCell').disabled=state.phase!=='implement';$('developmentCell').onchange=e=>{if(e.target.value!=='')action(()=>cellId=Number(e.target.value));};section.querySelectorAll('[data-develop]').forEach(b=>b.onclick=()=>action(()=>Research.start(state,active,cellId,b.dataset.develop),'Development started. Resources committed.'));if(d){$('visitProject').onclick=()=>{cellId=d.cell;render();};$('cancelDevelopment').disabled=state.phase!=='implement';$('cancelDevelopment').onclick=()=>action(()=>Research.cancel(state,active),'Project canceled; unused share returned.');}}
if(role==='military'&&regiment()){const r=regiment(),box=document.createElement('section');box.className='mini-card';box.innerHTML=`<label class="field">Regiment name<input id="regimentName" maxlength="60" value="${esc(r.name)}"></label><button id="renameRegiment">Rename regiment</button>`;checklist.after(box);$('regimentName').disabled=$('renameRegiment').disabled=state.phase!=='implement';$('renameRegiment').onclick=()=>action(()=>Civic.rename(state,active,'regiment',r.id,$('regimentName').value),'Regiment renamed.');}};
render();
